(()=>{'use strict';
const SERVICES=[
 {name:'Meta Ads',short:'Meta',tasks:['مراجعة الحساب الإعلاني والتتبع','تحليل الجمهور والحملات الحالية','إعداد خطة الاختبار والإطلاق','تقرير الأداء والتحسين الأسبوعي']},
 {name:'Google Ads',short:'Google',tasks:['فحص الربط والتحويلات','بحث الكلمات والمنتجات ذات الأولوية','إعداد حملات Search / Shopping','تحسين مصطلحات البحث والأداء']},
 {name:'SEO',short:'SEO',tasks:['تدقيق SEO الفني للمتجر','تحسين عناوين وتصنيفات المنتجات','مراجعة الفهرسة والروابط الداخلية','تقرير الظهور والزيارات العضوية']},
 {name:'التحليل والتتبع',short:'التتبع',tasks:['تدقيق GA4 وGTM والبيكسلات','اختبار أحداث ViewContent / AddToCart / Purchase','إعداد UTM ومعايير الإسناد','لوحة مؤشرات الأداء والتحقق من البيانات']},
 {name:'تصميم المتجر',short:'التصميم',tasks:['تقييم تجربة المستخدم والصفحة الرئيسية','تحسين صفحات المنتج وسهولة الشراء','مراجعة سرعة وأداء المتجر على الجوال','اختبار مسار الطلب والدفع']},
 {name:'Snapchat Ads',short:'Snap',tasks:['مراجعة حساب سناب والبيكسل','إعداد هيكل الحملات والجماهير','اختبار المواد الإعلانية','تحسين النتائج ورفع التقرير']},
 {name:'TikTok Ads',short:'TikTok',tasks:['فحص TikTok Pixel والأحداث','تجهيز خطة زوايا المحتوى','إطلاق اختبارات المجموعات الإعلانية','مراجعة CPA وROAS والتحسين']},
 {name:'إدارة المحتوى',short:'المحتوى',tasks:['إعداد استراتيجية وركائز المحتوى','تجهيز تقويم النشر','كتابة السكربتات والنصوص والتصاميم','اعتماد ونشر المحتوى وقياس التفاعل']}
];
const STAGES=[{id:'new',name:'مهام جديدة',color:'#9ca4b9'},{id:'progress',name:'قيد التنفيذ',color:'#3179e7'},{id:'review',name:'بانتظار المراجعة',color:'#e5a447'},{id:'done',name:'مكتملة',color:'#18a47b'}];
const I={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',check:'<path d="m5 12 4 4L19 6"/>',task:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 10 2 2 4-4M7 16h10"/>',team:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 7a4 4 0 1 0 0-8" transform="translate(2 1)"/><path d="M19 8a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v4M12 17h.01"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',arrow:'<path d="m9 18 6-6-6-6"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 1 1 8 0v4"/>',logout:'<path d="M10 3H4v18h6M14 7l5 5-5 5M19 12H8"/>',edit:'<path d="M4 20h16M5 15 16 4l4 4-11 11H5z"/>',users:'<circle cx="8" cy="8" r="4"/><path d="M2 21v-2a6 6 0 0 1 12 0v2M17 8a4 4 0 0 1 0 8M22 21v-2a5 5 0 0 0-4-4.8"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',chart:'<path d="M3 20V4M3 20h18M7 16l4-5 4 2 5-8"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',filter:'<path d="M4 5h16l-6 7v6l-4 2v-8z"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',chevron:'<path d="m6 9 6 6 6-6"/>',trash:'<path d="M4 6h16M10 3h4M6 6l1 15h10l1-15"/>',send:'<path d="m22 2-7 20-4-9-9-4L22 2ZM11 13l11-11"/>',back:'<path d="m15 18-6-6 6-6"/>',comment:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.5A9 9 0 1 1 21 11.5Z"/>'};
const icon=(name)=>`<svg class="svg" viewBox="0 0 24 24" aria-hidden="true">${I[name]||I.grid}</svg>`;
const el=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>{let w=String(s||'ن').trim().split(/\s+/).filter(x=>/\p{L}/u.test(x)).map(x=>x.length>3&&x.startsWith('ال')?x.slice(2):x);return (w.slice(0,2).map(x=>x.match(/\p{L}/u)[0]).join('')||'ن').toUpperCase()};
const uid=()=>('00000000-0000-4000-8000-'+Math.random().toString(16).slice(2).padEnd(12,'0').slice(0,12));
const today=()=>new Date().toISOString().slice(0,10);
const days=(n)=>{let x=new Date();x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)};
const fmtDate=d=>d?new Intl.DateTimeFormat('ar-YE',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'بدون موعد';
const cfg=window.NATIJ_CONFIG||{};
const isLive=!!(cfg.SUPABASE_URL&&cfg.SUPABASE_ANON_KEY);
let sb=null;
const storedInvite=(()=>{try{return localStorage.getItem('natij-invite')}catch(e){return null}})();
const urlInvite=new URLSearchParams(location.search).get('invite');
if(urlInvite){try{localStorage.setItem('natij-invite',urlInvite)}catch(e){}}
const isRecoveryLink=/type=recovery/.test(location.hash)||new URLSearchParams(location.search).get('type')==='recovery';
let state={mode:isLive?'live':'demo',user:'owner',profile:null,view:'dashboard',projectId:null,service:'all',search:'',modal:null,data:null,invitation:urlInvite||storedInvite,lastInviteLink:'',authPage:isRecoveryLink?'recovery':'login',loading:false,activityProject:'all',activityPerson:'all'};
const clearInvite=()=>{state.invitation=null;try{localStorage.removeItem('natij-invite')}catch(e){}};
const baseSeed=()=>{
 const p1=uid(),p2=uid(),p3=uid();let projects=[{id:p1,name:'متجر جديد',description:'نموذج مشروع تسويق إلكتروني متكامل',status:'active',created_at:new Date().toISOString()},{id:p2,name:'متجر الأفق',description:'إدارة الحملات وتحسين الظهور',status:'active',created_at:new Date().toISOString()},{id:p3,name:'متجر لمسة',description:'إدارة المحتوى والتصميم',status:'active',created_at:new Date().toISOString()}];
 let profiles=[{id:'owner',full_name:'المدير العام',email:'admin@natij.demo',is_owner:true},{id:'u1',full_name:'أحمد — Meta Ads',email:'ahmad@example.com'},{id:'u2',full_name:'محمد — Google Ads',email:'mohammed@example.com'},{id:'u3',full_name:'سالم — SEO',email:'salem@example.com'},{id:'u4',full_name:'ليان — تصميم',email:'layan@example.com'},{id:'u5',full_name:'خالد — TikTok',email:'khalid@example.com'}];
 let members=[{project_id:p1,user_id:'u1',role:'manager',specialty:'Meta Ads'},{project_id:p1,user_id:'u2',role:'member',specialty:'Google Ads'},{project_id:p1,user_id:'u3',role:'member',specialty:'SEO'},{project_id:p1,user_id:'u4',role:'member',specialty:'تصميم المتجر'},{project_id:p2,user_id:'u2',role:'manager',specialty:'Google Ads'},{project_id:p2,user_id:'u1',role:'member',specialty:'Meta Ads'},{project_id:p2,user_id:'u3',role:'member',specialty:'SEO'},{project_id:p2,user_id:'u5',role:'member',specialty:'TikTok Ads'},{project_id:p3,user_id:'u4',role:'member',specialty:'إدارة المحتوى'}];
 let services=SERVICES.map(s=>({project_id:p1,service:s.name})).concat(['Google Ads','Meta Ads','SEO'].map(s=>({project_id:p2,service:s})),['إدارة المحتوى','تصميم المتجر'].map(s=>({project_id:p3,service:s})));
 let tasks=[];SERVICES.forEach((s,i)=>s.tasks.forEach((title,j)=>tasks.push({id:uid(),project_id:p1,service:s.name,title,description:'',assigned_to:members.find(m=>m.project_id===p1&&m.specialty===s.name)?.user_id||null,priority:j===0?'high':'medium',status:(i+j)%5===0?'done':(i+j)%4===0?'review':(i+j)%3===0?'progress':'new',due_date:days((j+1)*3+i),created_at:new Date().toISOString()})));
 ['Google Ads','Meta Ads','SEO'].forEach(s=>tasks.push({id:uid(),project_id:p2,service:s,title:'تهيئة ومراجعة '+s,assigned_to:members.find(m=>m.project_id===p2&&m.specialty===s)?.user_id||null,priority:'medium',status:'progress',due_date:days(4),created_at:new Date().toISOString()}));
 const ago=m=>new Date(Date.now()-m*60000).toISOString();
 tasks.forEach(t=>{t.updated_at=t.created_at;t.updated_by=t.assigned_to||'owner'});
 let activity=[];let aid=1;const log=(project_id,task,actor,action,details,mins)=>activity.push({id:aid++,project_id,task_id:task?.id||null,actor_id:actor,action,details:{title:task?.title,...details},created_at:ago(mins)});
 log(p1,null,'owner','project_created',{name:'متجر جديد'},2900);
 tasks.filter(t=>t.project_id===p1&&t.status!=='new').slice(0,8).forEach((t,i)=>{log(p1,t,t.assigned_to||'u1','status_changed',{from:'new',to:t.status==='done'?'review':t.status},1500-i*90);if(t.status==='done')log(p1,t,'u1','status_changed',{from:'review',to:'done'},700-i*40);});
 log(p2,tasks.find(t=>t.project_id===p2),'u2','assigned',{to:'u2'},240);
 return{projects,profiles,members,services,tasks,comments:[],invites:[],activity,notifications:[]};
};
const DEMO_KEY='natij-demo-v5';
function demoLoad(){try{let d=JSON.parse(localStorage.getItem(DEMO_KEY));if(d&&Array.isArray(d.projects)&&Array.isArray(d.tasks)){d.activity=d.activity||[];d.notifications=d.notifications||[];return d;}}catch(e){}return baseSeed()}
function save(){if(!isLive){try{localStorage.setItem(DEMO_KEY,JSON.stringify(state.data));}catch(e){/* private previews may not expose browser storage */}}}
function data(){return state.data||{projects:[],profiles:[],members:[],services:[],tasks:[],comments:[],invites:[],activity:[],notifications:[]}}
// Demo-only mirrors of the database triggers (activity log + notifications)
function localLog(project_id,task,action,details={}){if(isLive)return;data().activity.unshift({id:Date.now()+Math.random(),project_id,task_id:task?.id||null,actor_id:me(),action,details:{title:task?.title,...details},created_at:new Date().toISOString()});}
function localNotify(user,project_id,task,title,body=''){if(isLive||!user||user===me())return;data().notifications.unshift({id:Date.now()+Math.random(),user_id:user,project_id,task_id:task?.id||null,title,body:body||task?.title||'',read_at:null,created_at:new Date().toISOString()});}
function localNotifyManagers(project_id,task,title){let ids=new Set(data().members.filter(m=>m.project_id===project_id&&m.role==='manager').map(m=>m.user_id));data().profiles.filter(p=>p.is_owner).forEach(p=>ids.add(p.id));ids.forEach(u=>localNotify(u,project_id,task,title));}
const owner=()=>isLive?!!state.profile?.is_owner:state.user==='owner';
const me=()=>isLive?state.profile?.id:state.user;
const profile=id=>data().profiles.find(p=>p.id===id)||{full_name:id?'مستخدم':'غير معين',email:''};
const memberProject=id=>data().members.some(m=>m.project_id===id&&m.user_id===me());
const canAccess=id=>owner()||memberProject(id);
const canManage=id=>owner()||data().members.some(m=>m.project_id===id&&m.user_id===me()&&m.role==='manager');
const visibleProjects=()=>data().projects.filter(p=>canAccess(p.id));
const visibleTasks=()=>data().tasks.filter(t=>canAccess(t.project_id));
const projectName=id=>data().projects.find(x=>x.id===id)?.name||'مشروع';
const projectServices=id=>data().services.filter(s=>s.project_id===id).map(s=>s.service);
const projTeam=id=>data().members.filter(m=>m.project_id===id);
const projectStats=id=>{let t=data().tasks.filter(x=>x.project_id===id);return{total:t.length,done:t.filter(x=>x.status==='done').length,percent:t.length?Math.round(t.filter(x=>x.status==='done').length/t.length*100):0}};
const stageName=s=>STAGES.find(x=>x.id===s)?.name||'جديدة';
const prio=p=>p==='high'?'عالية':p==='low'?'منخفضة':'متوسطة';
const managedProjects=()=>visibleProjects().filter(p=>canManage(p.id));
const managesAny=()=>owner()||managedProjects().length>0;
const profileLabel=()=>owner()?'المدير العام':managedProjects().length?'مدير مشروع':'عضو الفريق';
const timeAgo=iso=>{if(!iso)return '';let s=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);if(s<60)return 'الآن';let m=Math.floor(s/60);if(m<60)return `قبل ${m} د`;let h=Math.floor(m/60);if(h<24)return `قبل ${h} س`;let d=Math.floor(h/24);if(d<30)return d===1?'أمس':`قبل ${d} يوم`;return fmtDate(iso.slice(0,10))};
const personName=id=>id?profile(id).full_name:'النظام';
function activityText(a){let d=a.details||{},t=d.title?`«${esc(d.title)}»`:'';switch(a.action){
 case 'task_created':return `أنشأ مهمة ${t}`;
 case 'status_changed':return `نقل ${t} من <b>${esc(stageName(d.from))}</b> إلى <b>${esc(stageName(d.to))}</b>`;
 case 'assigned':return d.to?`أسند ${t} إلى <b>${esc(personName(d.to))}</b>`:`أزال المسؤول عن ${t}`;
 case 'task_edited':return `عدّل موعد/تفاصيل ${t}`;
 case 'commented':return `علّق على ${t}: <span class="muted">${esc(d.body||'')}</span>`;
 case 'member_joined':return `انضم إلى المشروع${d.specialty?' — '+esc(d.specialty):''}`;
 case 'member_removed':return `أزال <b>${esc(personName(d.user))}</b> من المشروع`;
 case 'project_created':return `أنشأ المشروع ${d.name?'«'+esc(d.name)+'»':''}`;
 case 'task_deleted':return `حذف المهمة ${t}`;
 default:return esc(a.action)}}
function activityItem(a,showProject=true){let p=profile(a.actor_id);return `<div class="activity-item">${profileAvatar(p)}<div class="activity-body"><div><strong>${esc(personName(a.actor_id))}</strong> ${activityText(a)}</div><small>${esc(timeAgo(a.created_at))}${showProject&&a.project_id?' · '+esc(projectName(a.project_id)):''}</small></div>${a.task_id&&data().tasks.some(t=>t.id===a.task_id)?`<button class="icon-btn" title="فتح المهمة" data-task-detail="${a.task_id}">${icon('arrow')}</button>`:''}</div>`}
const visibleActivity=()=>(data().activity||[]).filter(a=>canAccess(a.project_id)).sort((x,y)=>String(y.created_at).localeCompare(String(x.created_at)));
const myNotifications=()=>(data().notifications||[]).filter(n=>n.user_id===me()).sort((x,y)=>String(y.created_at).localeCompare(String(x.created_at)));
const unreadCount=()=>myNotifications().filter(n=>!n.read_at).length;
function memberStats(uid,pid){let t=data().tasks.filter(x=>x.assigned_to===uid&&(!pid||x.project_id===pid));return{done:t.filter(x=>x.status==='done').length,open:t.filter(x=>x.status==='new'||x.status==='progress').length,review:t.filter(x=>x.status==='review').length,late:t.filter(x=>x.due_date&&x.due_date<today()&&x.status!=='done').length}}
function toast(text,err=false){const t=el('toast');if(!t)return;t.textContent=text;t.style.background=err?'#a93556':'#181a46';t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3300)}
function setView(v,id){state.view=v;if(id!==undefined)state.projectId=id;state.service='all';state.search='';render();window.scrollTo({top:0,behavior:'smooth'});}
function statusTag(t){return `<span class="stage ${esc(t.status)}">${esc(stageName(t.status))}</span>`}
function profileAvatar(p){return `<span class="avatar" title="${esc(p.full_name)}">${esc(initials(p.full_name))}</span>`}
function btn(name,label,cls='secondary',extra=''){return `<button class="btn ${cls}" ${extra}>${icon(name)} ${label}</button>`}
function statsMarkup(){let t=visibleTasks(),ps=visibleProjects();let overdue=t.filter(x=>x.due_date&&x.due_date<today()&&x.status!=='done').length;let arr=[['المشاريع المتاحة',ps.length,'folder',''],['المهام قيد التنفيذ',t.filter(x=>x.status==='progress').length,'task','green'],['بانتظار المراجعة',t.filter(x=>x.status==='review').length,'clock','orange'],['المهام المتأخرة',overdue,'warning','red']];return `<div class="stats">${arr.map(([label,val,i,c],idx)=>`<div class="stat" style="animation-delay:${idx*.04}s"><div><small>${label}</small><div class="value">${val}</div></div><div class="stat-icon ${c}">${icon(i)}</div></div>`).join('')}</div>`}
function projectCard(p){let x=projectStats(p.id);return `<article class="project-card"><div class="proj-top"><span class="project-symbol">${esc(initials(p.name))}</span><span class="tiny-tag">${p.status==='active'?'نشط':'متوقف'}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'مشروع تسويق رقمي')}</p><div class="service-chips">${projectServices(p.id).slice(0,3).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}${projectServices(p.id).length>3?`<span class="chip">+${projectServices(p.id).length-3}</span>`:''}</div><div class="project-progress"><div class="progress-label"><span>نسبة إنجاز المهام</span><strong>${x.percent}%</strong></div><div class="progress-track"><span style="width:${x.percent}%"></span></div></div><div class="project-bottom"><div class="avatars">${projTeam(p.id).slice(0,4).map(m=>`<span class="mini-avatar" title="${esc(profile(m.user_id).full_name)}">${esc(initials(profile(m.user_id).full_name))}</span>`).join('')}</div><button class="btn sm secondary" data-open-project="${p.id}">فتح المشروع ${icon('arrow')}</button></div></article>`}
function taskLine(t){return `<div class="task-line"><span class="task-dot"></span><div class="task-info"><strong>${esc(t.title)}</strong><small>${esc(projectName(t.project_id))} · ${esc(t.service||'عام')} · ${esc(fmtDate(t.due_date))}</small></div>${statusTag(t)}<button class="icon-btn" title="تفاصيل" data-task-detail="${t.id}">${icon('arrow')}</button></div>`}
function dashboard(){let p=visibleProjects(),t=visibleTasks();let mine=t.filter(x=>x.assigned_to===me()&&x.status!=='done');return `<div class="page-head"><div><h1>${owner()?'صباح الإنجاز، أهلاً بك في ناتِج ✨':'أهلاً، '+esc(profile(me()).full_name)+' 👋'}</h1><p>${owner()?'كل مشاريعك وفرقك في مكان واحد':'هذه المشاريع والمهام المخصصة لك فقط'}</p></div>${owner()?btn('plus','مشروع جديد','primary','data-modal="project"'):''}</div>${!isLive?demoStrip():''}<section class="hero"><div class="hero-content"><span class="eyebrow">NATIJ FOR BUSINESS SOLUTIONS</span><h2>لأن النمو الحقيقي يُقاس بالنتائج.</h2><p>مشاريع أوضح، فريق منظم، ومهام توصل للناتج.</p></div><div class="hero-art"><img src="assets/logo.png" alt="شعار ناتِج الأصلي"></div></section>${statsMarkup()}<div class="two-cols"><section class="panel"><div class="panel-head"><h3>المشاريع</h3><button class="plain-link" data-view="projects">عرض الكل</button></div><div class="project-grid">${p.length?p.slice(0,4).map(projectCard).join(''):empty(owner()?'ما معك مشاريع حتى الآن':'بانتظار دعوة من الإدارة لمشروع')}</div></section><section class="panel"><div class="panel-head"><h3>${mine.length?'مهامك القادمة':'آخر المهام'}</h3><button class="plain-link" data-view="tasks">لوحة المهام</button></div><div class="task-list">${(mine.length?mine:t.filter(x=>x.status!=='done')).slice(0,7).map(taskLine).join('')||empty('ما في مهام حالياً')}</div></section></div><section class="panel section-pad"><div class="panel-head"><h3>آخر النشاطات — مين سوّى إيش</h3><button class="plain-link" data-view="activity">السجل الكامل</button></div><div class="activity-list">${visibleActivity().slice(0,8).map(a=>activityItem(a)).join('')||empty('ما في نشاط مسجّل بعد')}</div></section>`}
function demoStrip(){return `<div class="demo-strip"><div><strong>وضع المعاينة:</strong> تقدر تجرب الموقع الآن، لكن هذه بيانات تجريبية على جهازك وليست حسابات حقيقية أو قاعدة بيانات آمنة.</div><label>جرّب كـ <select id="demo-user"><option value="owner" ${state.user==='owner'?'selected':''}>المدير العام</option>${data().profiles.filter(p=>p.id!=='owner').map(p=>`<option value="${p.id}" ${state.user===p.id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></label></div>`}
function empty(t='لا توجد بيانات'){return `<div class="empty">${icon('folder')}<strong>${esc(t)}</strong><p>تقدر تبدأ إضافة مشروع أو مهمة من القائمة.</p></div>`}
function projectsView(){let p=visibleProjects(),s=state.search.trim().toLowerCase();if(s)p=p.filter(x=>x.name.toLowerCase().includes(s));return `<div class="page-head"><div><h1>المشاريع</h1><p>${owner()?'كل مشاريع العملاء':'فقط المشاريع التي أنت ضمن فريقها'}</p></div>${owner()?btn('plus','إضافة مشروع','primary','data-modal="project"'):''}</div>${!isLive?demoStrip():''}<div class="toolbar"><input class="select" style="min-width:250px" placeholder="بحث عن مشروع..." value="${esc(state.search)}" id="project-search"/><span class="tiny-tag blue">${p.length} مشاريع</span></div><div class="project-grid">${p.map(projectCard).join('')||empty('لم يتم العثور على مشروع')}</div>`}
function projectView(){let p=visibleProjects().find(x=>x.id===state.projectId);if(!p)return empty('هذا المشروع غير متاح لحسابك');let t=data().tasks.filter(x=>x.project_id===p.id),st=projectStats(p.id);return `<div class="page-head"><div><span class="eyebrow">المشاريع / ${esc(p.name)}</span><h1>${esc(p.name)}</h1><p>${esc(p.description||'إدارة وتسليم مهام المشروع')}</p></div><div class="page-actions">${canManage(p.id)?btn('plus','مهمة جديدة','primary','data-modal="task"'):''}${canManage(p.id)?btn('users','إضافة عضو','secondary','data-modal="invite"'):''}</div></div>${!isLive?demoStrip():''}<div class="stats"><div class="stat"><div><small>مهام المشروع</small><div class="value">${st.total}</div></div><div class="stat-icon">${icon('task')}</div></div><div class="stat"><div><small>المكتملة</small><div class="value">${st.done}</div></div><div class="stat-icon green">${icon('check')}</div></div><div class="stat"><div><small>فريق المشروع</small><div class="value">${projTeam(p.id).length}</div></div><div class="stat-icon">${icon('team')}</div></div><div class="stat"><div><small>نسبة الإنجاز</small><div class="value">${st.percent}%</div></div><div class="stat-icon orange">${icon('chart')}</div></div></div><div class="panel" style="margin-bottom:17px"><div class="panel-head"><h3>خدمات المشروع</h3><button class="plain-link" data-view="tasks">عرض لوحة المهام</button></div><div class="service-chips">${projectServices(p.id).map(s=>`<button class="chip" data-project-service="${esc(s)}">${esc(s)}</button>`).join('')}</div></div><div class="two-cols"><section class="panel"><div class="panel-head"><h3>مهام المشروع</h3><span class="eyebrow">${t.length} مهمة</span></div><div class="task-list">${t.slice(0,9).map(taskLine).join('')||empty('لا توجد مهام')}</div></section><section class="panel"><div class="panel-head"><h3>فريق العمل</h3></div><div class="member-list" style="grid-template-columns:1fr">${projTeam(p.id).map(m=>memberCard(m,p.id)).join('')||empty('لم يتم إضافة فريق بعد')}</div></section></div><section class="panel section-pad"><div class="panel-head"><h3>سجل نشاط المشروع</h3><button class="plain-link" data-activity-project="${p.id}">عرض الكل</button></div><div class="activity-list">${visibleActivity().filter(a=>a.project_id===p.id).slice(0,12).map(a=>activityItem(a,false)).join('')||empty('ما في نشاط بعد')}</div></section>`}
function tasksView(){let t=visibleTasks(),p=state.projectId&&visibleProjects().some(x=>x.id===state.projectId)?state.projectId:'all';if(p!=='all')t=t.filter(x=>x.project_id===p);if(state.service!=='all')t=t.filter(x=>x.service===state.service);let srv=p==='all'?[...new Set(visibleTasks().map(x=>x.service).filter(Boolean))]:projectServices(p);if(state.search)t=t.filter(x=>x.title.includes(state.search)||x.service?.includes(state.search));let manage=p==='all'?owner():canManage(p);return `<div class="page-head"><div><h1>لوحة المهام</h1><p>اسحب البطاقة للمرحلة التالية أو غيّر الحالة من القائمة</p></div>${manage?btn('plus','مهمة جديدة','primary','data-modal="task"'):''}</div>${!isLive?demoStrip():''}<div class="toolbar"><select class="select" id="task-project-filter"><option value="all">جميع مشاريعي</option>${visibleProjects().map(x=>`<option value="${x.id}" ${x.id===p?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select class="select" id="task-service-filter"><option value="all">كل التخصصات</option>${srv.map(s=>`<option ${s===state.service?'selected':''}>${esc(s)}</option>`).join('')}</select><input class="select" id="task-search" value="${esc(state.search)}" placeholder="ابحث في المهام" /></div><div class="kanban">${STAGES.map(s=>`<div class="kanban-col" data-drop-stage="${s.id}"><div class="kanban-title"><span><span class="task-dot" style="background:${s.color};display:inline-block;margin-left:7px"></span>${s.name}</span><span class="count">${t.filter(x=>x.status===s.id).length}</span></div>${t.filter(x=>x.status===s.id).map(taskCard).join('')||'<div style="font-size:12px;color:#a0a7ba;text-align:center;padding:20px 6px">اسحب المهمة إلى هنا</div>'}</div>`).join('')}</div>`}
function taskCard(t){let can=canManage(t.project_id)||t.assigned_to===me();let stages=STAGES.filter(s=>s.id!=='done'||canManage(t.project_id));return `<article class="task-card" data-task-detail="${t.id}" draggable="${can}"><small>${esc(t.service||'عام')} · ${esc(projectName(t.project_id))}</small><h4>${esc(t.title)}</h4><div class="member-pill">${icon('users')} ${esc(t.assigned_to?profile(t.assigned_to).full_name:'لم يُعين بعد')}</div><div class="task-meta"><span class="priority ${esc(t.priority)}">${prio(t.priority)}</span><small class="${t.due_date&&t.due_date<today()&&t.status!=='done'?'late':''}">${esc(fmtDate(t.due_date))}</small></div>${t.updated_at&&t.updated_by?`<div class="updated-by">${icon('clock')} ${esc(personName(t.updated_by))} · ${esc(timeAgo(t.updated_at))}</div>`:''}${can?`<div style="margin-top:11px"><select class="change-status" data-task-status="${t.id}" aria-label="حالة المهمة">${stages.map(s=>`<option value="${s.id}" ${t.status===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div>`:''}</article>`}
function memberCard(m,pid,withActions=false){let p=profile(m.user_id),st=memberStats(m.user_id,pid);let canRemove=withActions&&m.user_id!==me()&&(owner()||(canManage(m.project_id)&&m.role==='member'));return `<div class="member-card">${profileAvatar(p)}<div style="min-width:0"><strong>${esc(p.full_name)}</strong><small>${esc(m.specialty||'عضو فريق')}</small><div class="member-stats"><span class="ok">✓ ${st.done} مكتملة</span><span>${st.open} جارية</span>${st.review?`<span class="rev">${st.review} مراجعة</span>`:''}${st.late?`<span class="bad">${st.late} متأخرة</span>`:''}</div></div><div class="member-side"><span class="tiny-tag ${m.role==='manager'?'amber':'blue'}">${m.role==='manager'?'مدير المشروع':'عضو'}</span>${canRemove?`<button class="btn sm danger" data-remove-member="${esc(m.project_id)}|${esc(m.user_id)}">إزالة</button>`:''}</div></div>`}
function teamView(){let p=visibleProjects(),pid=state.projectId&&p.some(x=>x.id===state.projectId)?state.projectId:(p[0]?.id||null);let m=pid?projTeam(pid):[];return `<div class="page-head"><div><h1>الفريق والصلاحيات</h1><p>أعضاء كل مشروع لا يشوفوا أي مشروع آخر غير مخوّلين به</p></div>${managesAny()?btn('plus','دعوة عضو','primary','data-modal="invite"'):''}</div>${!isLive?demoStrip():''}<div class="toolbar"><select id="team-project-filter" class="select">${p.map(x=>`<option value="${x.id}" ${x.id===pid?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="tiny-tag blue">${m.length} أعضاء</span></div><div class="panel"><div class="panel-head"><h3>أعضاء ${esc(projectName(pid))}</h3>${icon('lock')}</div><div class="member-list">${m.map(x=>memberCard(x,pid,true)).join('')||empty('لا يوجد أعضاء في هذا المشروع')}</div></div>${pid&&canManage(pid)?`<section class="panel section-pad"><div class="panel-head"><h3>دعوات الفريق</h3><span class="eyebrow">ترسل الرابط على واتساب أو أي تطبيق</span></div>${(data().invites||[]).filter(x=>x.project_id===pid).slice(0,15).map(x=>`<div class="task-line"><div class="task-info"><strong>${esc(x.email)}</strong><small>${esc(projectName(x.project_id))} · ${x.accepted_at?'تم الانضمام':'بانتظار التسجيل'}</small></div>${!x.accepted_at?`<button class="btn sm secondary" data-copy-invite="${esc(x.code)}">${icon('copy')} نسخ الدعوة</button>`:''}</div>`).join('')||empty('لا توجد دعوات بعد')}</section>`:''}`}
function activityView(){let ps=visibleProjects(),pid=state.activityProject,who=state.activityPerson;let list=visibleActivity();if(pid!=='all')list=list.filter(a=>a.project_id===pid);if(who!=='all')list=list.filter(a=>a.actor_id===who);let people=[...new Set(visibleActivity().map(a=>a.actor_id).filter(Boolean))];return `<div class="page-head"><div><h1>سجل النشاط</h1><p>كل حركة في المشاريع: مين أنجز، مين نقل المهمة، ومتى — بدل «فلان وين أنت؟»</p></div></div>${!isLive?demoStrip():''}<div class="toolbar"><select class="select" id="activity-project-filter"><option value="all">كل المشاريع</option>${ps.map(x=>`<option value="${x.id}" ${x.id===pid?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select class="select" id="activity-person-filter"><option value="all">كل الأشخاص</option>${people.map(u=>`<option value="${u}" ${u===who?'selected':''}>${esc(personName(u))}</option>`).join('')}</select><span class="tiny-tag blue">${list.length} حركة</span></div><div class="panel"><div class="activity-list">${list.slice(0,200).map(a=>activityItem(a,pid==='all')).join('')||empty('ما في نشاط مطابق')}</div></div>`}
function notificationsModal(){let n=myNotifications();return modalWrap('الإشعارات',`<div class="activity-list">${n.slice(0,40).map(x=>`<div class="notif ${x.read_at?'':'unread'}"><span class="task-dot"></span><div class="activity-body"><strong>${esc(x.title)}</strong><small>${esc(x.body||'')}${x.project_id?' · '+esc(projectName(x.project_id)):''} · ${esc(timeAgo(x.created_at))}</small></div>${x.task_id&&data().tasks.some(t=>t.id===x.task_id)?`<button class="icon-btn" data-task-detail="${x.task_id}">${icon('arrow')}</button>`:''}</div>`).join('')||'<p class="muted">ما عندك إشعارات حالياً.</p>'}</div>`)}
function calendarView(){let a=visibleTasks().filter(t=>t.due_date&&t.status!=='done').sort((x,y)=>x.due_date.localeCompare(y.due_date));return `<div class="page-head"><div><h1>التقويم والمواعيد</h1><p>مواعيد تسليم المهام مرتبة من الأقرب</p></div></div>${!isLive?demoStrip():''}<div class="panel"><div class="calendar-list">${a.slice(0,60).map(t=>{let d=new Date(t.due_date+'T12:00:00');return `<div class="calendar-entry"><div class="date-box">${d.getDate()}<small>${new Intl.DateTimeFormat('ar-YE',{month:'short'}).format(d)}</small></div><div style="flex:1"><strong>${esc(t.title)}</strong><div class="muted small">${esc(projectName(t.project_id))} · ${esc(t.service||'عام')}</div></div>${statusTag(t)}<button class="icon-btn" data-task-detail="${t.id}">${icon('arrow')}</button></div>`}).join('')||empty('لا توجد مواعيد قادمة')}</div></div>`}
function settingsView(){return `<div class="page-head"><div><h1>الإعدادات</h1><p>معلومات حسابك وطريقة تشغيل النظام</p></div></div><div class="two-cols"><div class="panel"><h3>الملف الشخصي</h3><div class="member-card section-pad">${profileAvatar(profile(me()))}<div><strong>${esc(profile(me()).full_name)}</strong><small>${esc(profile(me()).email)}</small><span class="tiny-tag blue">${profileLabel()}</span></div></div>${isLive?`<div class="field section-pad"><label>تعديل الاسم</label><input id="my-fullname" value="${esc(profile(me()).full_name)}" /></div>${btn('check','حفظ الاسم','primary','data-save-profile="1"')}`:''}</div><div class="panel"><h3>حالة التشغيل</h3><div class="dialog-info section-pad">${isLive?'النظام متصل بقاعدة بيانات Supabase. عرض المشاريع والأعضاء يخضع لصلاحيات قاعدة البيانات.':'هذه نسخة تجريبية محلية. لم يتم ربط قاعدة بيانات أو تشغيل صلاحيات الفريق الحقيقية بعد.'}</div>${isLive?`<p class="small muted">الموقع مستضاف على Hostinger وبياناته في Supabase. كل مستخدم يرى فقط المشاريع التي دُعي إليها، والقاعدة تفرض ذلك حتى لو حاول أحد تجاوز الواجهة.</p>`:`<p class="small muted">لتفعيل النسخة الحقيقية: ضع رابط Supabase والمفتاح العام في config.js.</p><p class="small muted">لا تضع بيانات عملاء حقيقية في وضع المعاينة.</p>`}${!isLive?btn('trash','إعادة ضبط بيانات التجربة','danger','data-reset-demo="1"'):''}</div></div>`}
const navItems=[['dashboard','لوحة التحكم','grid'],['projects','المشاريع','folder'],['tasks','لوحة المهام','task'],['activity','سجل النشاط','clock'],['team','الفريق','team'],['calendar','التقويم','calendar'],['settings','الإعدادات','settings']];
function page(){let h={dashboard:dashboard,projects:projectsView,project:projectView,tasks:tasksView,activity:activityView,team:teamView,calendar:calendarView,settings:settingsView};return (h[state.view]||dashboard)()}
function layout(){let viewTitle=navItems.find(x=>x[0]===state.view)?.[1]||'تفاصيل المشروع';return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="assets/logo.png" alt="شعار ناتِج الأصلي"/><div><strong class="brand-title">NATIJ</strong><small>WORKSPACE</small></div></div><div class="sidebar-caption">مساحة العمل</div><nav class="nav">${navItems.map(([id,n,i])=>`<button class="nav-btn ${id===state.view?'active':''}" data-view="${id}">${icon(i)}<span>${n}</span>${id==='projects'?`<small class="nav-count">${visibleProjects().length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><span class="diamond"></span><strong>كل شغلك في مكان واحد.</strong><p>فريق واحد، مهام واضحة، وناتج يمكن قياسه.</p></div></div></aside><div class="main"><header class="topbar"><div><div class="breadcrumb">NATIJ Workspace ${icon('arrow')} ${esc(viewTitle)}</div><h2>${esc(viewTitle)}</h2></div><div class="top-actions"><span class="badge-light">${icon('lock')} ${esc(profileLabel())}</span><button class="circle-btn bell-btn" data-modal="notifications" aria-label="الإشعارات" title="الإشعارات">${icon('bell')}<span id="notif-count" class="notif-count" ${unreadCount()?'':'hidden'}>${unreadCount()}</span></button>${profileAvatar(profile(me()))}${isLive?`<button class="circle-btn" id="signout" aria-label="تسجيل الخروج" title="تسجيل الخروج">${icon('logout')}</button>`:''}</div></header><main class="content">${page()}</main></div></div><nav class="mobile-nav">${navItems.slice(0,5).map(([id,n,i])=>`<button class="${id===state.view?'active':''}" data-view="${id}">${icon(i)}${n}</button>`).join('')}</nav>`}
function modalWrap(title,content){return `<div class="modal-back" data-close-overlay="1"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h3>${esc(title)}</h3><button class="icon-btn" data-modal-close="1">${icon('close')}</button></div>${content}</div></div>`}
function modalContent(){let m=state.modal;if(!m)return '';if(m==='notifications')return notificationsModal();if(m==='project'){return modalWrap('إضافة مشروع جديد',`<form id="form-project"><div class="field"><label>اسم المتجر أو المشروع</label><input name="name" placeholder="مثلاً: متجر جديد" required minlength="2" maxlength="110"/></div><div class="field"><label>وصف مختصر (اختياري)</label><textarea name="description" rows="2" placeholder="خدمات التسويق وإدارة المتجر"></textarea></div><label class="eyebrow" style="display:block;margin:5px 0 10px">اختر التخصصات التي سيشملها المشروع</label><div class="services-grid">${SERVICES.map(s=>`<label class="service-check"><input type="checkbox" name="service" value="${esc(s.name)}" checked>${esc(s.name)}</label>`).join('')}</div><div class="dialog-info">بيتم إنشاء 4 مهام بداية لكل تخصص تختاره، وتقدر تضيف الفريق بعدها.</div><div class="modal-footer"><button class="btn primary" type="submit">${icon('plus')} إنشاء المشروع والمهام</button><button type="button" class="btn secondary" data-modal-close="1">إلغاء</button></div></form>`)}
 if(m==='task'){let p=visibleProjects().filter(x=>canManage(x.id));let chosen=(state.projectId&&p.some(x=>x.id===state.projectId))?state.projectId:p[0]?.id;return modalWrap('مهمة جديدة',`<form id="form-task"><div class="field"><label>المشروع</label><select name="project_id" id="form-task-project">${p.map(x=>`<option value="${x.id}" ${x.id===chosen?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>عنوان المهمة</label><input name="title" maxlength="220" minlength="3" required placeholder="مثلاً: إطلاق حملة Meta Ads"></div><div class="field"><label>التخصص</label><select name="service" id="form-task-service">${projectServices(chosen).map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>المسؤول عن التنفيذ</label><select name="assigned_to" id="form-task-assignee"><option value="">غير معين</option>${projTeam(chosen).map(x=>`<option value="${x.user_id}">${esc(profile(x.user_id).full_name)}</option>`).join('')}</select></div><div class="field"><label>وصف المهمة</label><textarea name="description" rows="3" placeholder="تعليمات وملاحظات التنفيذ"></textarea></div><div class="two-field"><div class="field"><label>موعد التسليم</label><input type="date" name="due_date" value="${days(5)}"></div><div class="field"><label>الأولوية</label><select name="priority"><option value="medium">متوسطة</option><option value="high">عالية</option><option value="low">منخفضة</option></select></div></div><div class="modal-footer"><button type="submit" class="btn primary">${icon('check')} حفظ المهمة</button><button type="button" class="btn secondary" data-modal-close="1">إلغاء</button></div></form>`)}
 if(m==='invite'){let p=managedProjects(),chosen=state.projectId&&p.some(x=>x.id===state.projectId)?state.projectId:p[0]?.id;return modalWrap('دعوة عضو إلى مشروع',`<form id="form-invite"><div class="field"><label>البريد الإلكتروني للموظف</label><input required type="email" name="email" placeholder="employee@gmail.com"></div><div class="field"><label>المشروع الذي يسمح له بدخوله</label><select name="project_id">${p.map(x=>`<option value="${x.id}" ${x.id===chosen?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>الصلاحية</label><select name="role"><option value="member">عضو فريق</option>${owner()?'<option value="manager">مدير مشروع</option>':''}</select></div><div class="field"><label>التخصص</label><select name="specialty">${SERVICES.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="dialog-info">بعد الإنشاء انسخ رابط الدعوة وأرسله للموظف عبر واتساب. يسجّل بنفس البريد الذي كتبته هنا، ولا يقدر يشوف أي مشروع غير الذي دعوته إليه.</div><div class="modal-footer"><button type="submit" class="btn primary">${icon('link')} إنشاء رابط الدعوة</button><button type="button" class="btn secondary" data-modal-close="1">إلغاء</button></div></form>`)}
 if(m==='invite-link'){return modalWrap('تم إنشاء الدعوة',`<p class="muted small">انسخ هذا الرابط وأرسله إلى الموظف الذي حددت بريده:</p><div class="field"><input id="generated-link" dir="ltr" readonly value="${esc(state.lastInviteLink)}"></div><div class="modal-footer"><button class="btn primary" data-copy-link="1">${icon('copy')} نسخ الرابط</button><button class="btn secondary" data-modal-close="1">إغلاق</button></div>`)}
 if(m?.startsWith('task:')){let t=data().tasks.find(x=>x.id===m.slice(5));if(!t)return '';let allow=canManage(t.project_id),can=allow||t.assigned_to===me(),com=data().comments.filter(c=>c.task_id===t.id);return modalWrap('تفاصيل المهمة',`<div class="details-content"><span class="chip">${esc(t.service||'عام')}</span><h2 style="font-size:20px;margin:12px 0 4px">${esc(t.title)}</h2><p>${esc(t.description||'لا يوجد وصف للمهمة حتى الآن.')}</p><div class="service-chips"><span class="chip">${esc(projectName(t.project_id))}</span><span class="chip">${esc(profile(t.assigned_to).full_name)}</span><span class="chip">${esc(fmtDate(t.due_date))}</span></div><div class="divider"></div>${allow?`<form id="form-task-edit" data-task-id="${t.id}"><div class="field"><label>المسؤول عن التنفيذ</label><select name="assigned_to"><option value="">بدون مسؤول</option>${projTeam(t.project_id).map(m=>`<option value="${m.user_id}" ${m.user_id===t.assigned_to?'selected':''}>${esc(profile(m.user_id).full_name)}</option>`).join('')}</select></div><div class="two-field"><div class="field"><label>موعد التسليم</label><input name="due_date" type="date" value="${esc(t.due_date||'')}"></div><div class="field"><label>الأولوية</label><select name="priority">${['high','medium','low'].map(p=>`<option value="${p}" ${t.priority===p?'selected':''}>${prio(p)}</option>`).join('')}</select></div></div><div class="field"><label>تعليمات المهمة</label><textarea name="description" rows="2" maxlength="3000">${esc(t.description||'')}</textarea></div><button class="btn sm secondary" type="submit">${icon('check')} حفظ توزيع المهمة</button></form><div class="divider"></div>`:''}<div class="field"><label>حالة المهمة</label><select id="detail-status" data-task-status="${t.id}" ${can?'':'disabled'}>${STAGES.filter(s=>s.id!=='done'||allow||t.status==='done').map(s=>`<option value="${s.id}" ${t.status===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><h3>التعليقات والمتابعة</h3>${com.map(c=>`<div class="task-line"><div>${profileAvatar(profile(c.author_id))}</div><div class="task-info"><strong>${esc(profile(c.author_id).full_name)}</strong><small>${esc(c.body)}</small></div></div>`).join('')||'<p>ما في تعليقات بعد.</p>'}<form id="form-comment" data-task-id="${t.id}"><div class="field"><textarea required name="body" rows="2" maxlength="2500" placeholder="اكتب ملاحظة أو تحديثاً للفريق..."></textarea></div><button class="btn primary" type="submit">${icon('send')} إضافة تعليق</button></form><div class="divider"></div><h3>سجل المهمة</h3><div class="activity-list">${visibleActivity().filter(a=>a.task_id===t.id).slice(0,30).map(a=>activityItem(a,false).replace(/<button class="icon-btn"[^]*?<\/button>/,'')).join('')||'<p>ما في حركة مسجّلة على المهمة بعد.</p>'}</div>${allow?`<div class="divider"></div><button class="btn sm danger" data-delete-task="${t.id}">${icon('trash')} حذف المهمة</button>`:''}</div>`)}
 return ''}
function render(){const a=el('app');if(!a)return;if(isLive&&(!state.profile||state.authPage==='recovery')){a.innerHTML=authMarkup();return;}a.innerHTML=layout()+(state.modal?modalContent():'');}
function recoveryMarkup(){return `<h1>تعيين كلمة مرور جديدة</h1><p>اكتب كلمة المرور الجديدة لحسابك.</p><form id="form-auth"><div class="field"><label>كلمة المرور الجديدة</label><input name="password" type="password" autocomplete="new-password" minlength="6" required placeholder="6 أحرف أو أكثر"></div><div class="field"><label>تأكيد كلمة المرور</label><input name="password2" type="password" autocomplete="new-password" minlength="6" required></div><button class="btn primary full" type="submit">حفظ كلمة المرور ${icon('arrow')}</button></form><div style="margin-top:17px"><button class="plain-link" data-auth-page="login">إلغاء والعودة لتسجيل الدخول</button></div>`}
function authMarkup(){if(state.authPage==='recovery')return `<div class="sign-page"><div class="sign-art"><img src="assets/logo-wide.png" alt="شعار ناتِج" style="width:min(590px,95%);max-width:none;border-radius:10px"/><h2>مساحة عمل ناتِج</h2></div><div class="sign-form"><div class="sign-box"><div class="eyebrow">NATIJ Workspace</div>${recoveryMarkup()}</div></div></div>`;let reg=state.authPage==='signup',forgot=state.authPage==='forgot';return `<div class="sign-page"><div class="sign-art"><img src="assets/logo-wide.png" alt="شعار ناتِج من دليل الهوية" style="width:min(590px,95%);max-width:none;border-radius:10px"/><h2>مساحة عمل ناتِج</h2><p>كل فريق يرى مشروعه فقط — والإدارة ترى الصورة كاملة.</p></div><div class="sign-form"><div class="sign-box"><div class="eyebrow">NATIJ Workspace</div><h1>${forgot?'استعادة كلمة المرور':reg?'إنشاء حساب بدعوة':'تسجيل الدخول'}</h1><p>${state.invitation?'عند الدخول سنربط حسابك بالمشروع الذي تمت دعوتك إليه.':'سجّل بإيميلك وكلمة المرور.'}</p><form id="form-auth">${reg?`<div class="field"><label>الاسم</label><input required name="name" placeholder="الاسم الكامل"></div>`:''}<div class="field"><label>البريد الإلكتروني</label><input required type="email" name="email" autocomplete="email" placeholder="you@example.com"></div>${!forgot?`<div class="field"><label>كلمة المرور</label><input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="6" required placeholder="6 أحرف أو أكثر"></div>`:''}<button class="btn primary full" type="submit">${forgot?'إرسال رابط الاستعادة':reg?'إنشاء الحساب':'الدخول للنظام'} ${icon('arrow')}</button></form><div style="display:flex;gap:16px;margin-top:17px;flex-wrap:wrap">${reg?'<button class="plain-link" data-auth-page="login">عندي حساب بالفعل</button>':`<button class="plain-link" data-auth-page="${'signup'}">${state.invitation?'معي دعوة — إنشاء حساب':'إنشاء حساب جديد'}</button>`}${!forgot?'<button class="plain-link" data-auth-page="forgot">نسيت كلمة المرور؟</button>':'<button class="plain-link" data-auth-page="login">رجوع لتسجيل الدخول</button>'}</div><div class="install-banner">${icon('lock')} إنشاء حساب لا يمنحك مشاهدة أي مشروع؛ الدخول للمشاريع يتطلب دعوة أو صلاحية المدير.</div></div></div></div>`}
async function start(){if(isLive){if(!window.supabase){await new Promise(resolve=>{let t=document.createElement('script');t.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js';t.onload=resolve;t.onerror=resolve;document.head.appendChild(t);});}if(!window.supabase){el('app').innerHTML='<div class="empty" style="margin:12vh auto;max-width:500px">لم يتم تحميل مكتبة تسجيل الدخول. تحقق من الاتصال بالإنترنت.</div>';return;}sb=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY);sb.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){state.profile=null;state.data=null;render();}else if(event==='PASSWORD_RECOVERY'){state.authPage='recovery';render()}});let {data:r,error}=await sb.auth.getSession();if(error)toast('تعذر الاتصال بخدمة تسجيل الدخول',true);if(r?.session){await refreshLive();}else{if(state.authPage==='recovery'){state.authPage='forgot';toast('رابط الاستعادة منتهي أو غير صالح، اطلب رابطاً جديداً',true);}else if(state.invitation)state.authPage='signup';render();}
 setInterval(pollNotifications,45000);window.addEventListener('focus',()=>{if(state.profile&&!state.modal&&!document.activeElement?.matches?.('input,textarea,select'))refreshLive();});}else{state.data=demoLoad();render()}}
async function pollNotifications(){if(!isLive||!state.profile||document.hidden)return;let{data:n,error}=await sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(50);if(error||!n||!state.data)return;let before=new Set((state.data.notifications||[]).map(x=>x.id));let fresh=n.filter(x=>!before.has(x.id)&&!x.read_at);state.data.notifications=n;let c=el('notif-count');if(c){let u=unreadCount();c.textContent=u;c.hidden=!u;}if(fresh.length)toast('🔔 '+fresh[0].title+(fresh.length>1?` (+${fresh.length-1})`:''));if(state.modal==='notifications')render();}
async function refreshLive(){const {data:u,error:eu}=await sb.auth.getUser();if(eu||!u?.user){state.profile=null;render();return;}let [{data:p,error:e1},{data:projects,error:e2},{data:profiles,error:e3},{data:members,error:e4},{data:services,error:e5},{data:tasks,error:e6},{data:comments,error:e7}]=await Promise.all([sb.from('profiles').select('*').eq('id',u.user.id).single(),sb.from('projects').select('*'),sb.from('profiles').select('id,full_name,email,is_owner'),sb.from('project_members').select('*'),sb.from('project_services').select('*'),sb.from('tasks').select('*').order('created_at',{ascending:true}),sb.from('task_comments').select('*').order('created_at',{ascending:true})]);if(e1||!p){toast('تعذر تحميل حسابك. حاول تسجيل الدخول مرة أخرى.',true);state.profile=null;render();return;}
 let [{data:activity,error:e8},{data:notifications},{data:invites}]=await Promise.all([sb.from('activity_log').select('*').order('created_at',{ascending:false}).limit(400),sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(50),sb.from('project_invitations').select('*').order('created_at',{ascending:false}).limit(60)]);
 state.profile=p;state.data={projects:projects||[],profiles:profiles||[p],members:members||[],services:services||[],tasks:tasks||[],comments:comments||[],invites:invites||[],activity:activity||[],notifications:notifications||[]};if(state.invitation){let code=state.invitation;clearInvite();if(location.search.includes('invite='))history.replaceState({},'',location.pathname);let res=await sb.rpc('claim_invitation',{p_code:code});if(!res.error&&res.data===true){toast('تم الانضمام إلى المشروع بنجاح');return refreshLive();}else if(res.error)toast('تعذر قبول الدعوة: '+res.error.message,true);}
 if([e2,e3,e4,e5,e6,e7,e8].some(Boolean))toast('هناك مشكلة في قراءة بعض البيانات. راجع إعدادات قاعدة البيانات.',true);render();}
async function projectCreate(form){let name=form.get('name')?.trim(),description=form.get('description')?.trim(),services=form.getAll('service');if(!name||!services.length)return toast('أدخل اسم المشروع وحدد خدمة على الأقل',true);let newId=null;if(isLive){const {data:pid,error}=await sb.rpc('create_project_from_template',{p_name:name,p_description:description||'',p_services:services});if(error)return toast(error.message,true);newId=pid;await refreshLive();}else{let id=uid();newId=id;data().projects.unshift({id,name,description,status:'active',created_at:new Date().toISOString()});services.forEach(s=>{data().services.push({project_id:id,service:s});SERVICES.find(x=>x.name===s)?.tasks.forEach((title,j)=>data().tasks.push({id:uid(),project_id:id,service:s,title,description:'',assigned_to:null,priority:j===0?'high':'medium',status:'new',due_date:days(j*3+3),created_at:new Date().toISOString(),updated_at:new Date().toISOString(),updated_by:me()}));});localLog(id,null,'project_created',{name});save();}state.modal=null;if(newId){state.projectId=newId;state.view='project';}else state.view='projects';render();toast('تم إنشاء المشروع مع مهامه الجاهزة — أضف الفريق الآن');}
async function taskCreate(form){let t={project_id:form.get('project_id'),title:form.get('title')?.trim(),service:form.get('service'),assigned_to:form.get('assigned_to')||null,description:form.get('description')||'',priority:form.get('priority'),due_date:form.get('due_date')||null,status:'new'};if(!canManage(t.project_id))return toast('لا تملك صلاحية إضافة مهام في هذا المشروع',true);if(isLive){const {error}=await sb.from('tasks').insert(t);if(error)return toast(error.message,true);await refreshLive();}else{let n={id:uid(),...t,created_at:new Date().toISOString(),updated_at:new Date().toISOString(),updated_by:me()};data().tasks.unshift(n);localLog(n.project_id,n,'task_created');if(n.assigned_to)localNotify(n.assigned_to,n.project_id,n,'مهمة جديدة لك');save();}state.modal=null;render();toast('تمت إضافة المهمة');}
async function inviteCreate(form){let email=String(form.get('email')||'').toLowerCase().trim(),project_id=form.get('project_id'),role=form.get('role'),specialty=form.get('specialty');if(!canManage(project_id))return toast('الدعوة لمدير هذا المشروع أو المدير العام فقط',true);if(role==='manager'&&!owner())return toast('تعيين مدير مشروع للمدير العام فقط',true);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('البريد الإلكتروني غير صحيح',true);let code=uid();if(isLive){let {data:r,error}=await sb.from('project_invitations').insert({email,project_id,role,specialty,created_by:me()}).select('code').single();if(error)return toast(error.message,true);code=r.code;await refreshLive();}else{let p=data().profiles.find(x=>x.email?.toLowerCase()===email);if(!p){p={id:uid(),email,full_name:email.split('@')[0],is_owner:false};data().profiles.push(p);}if(!data().members.some(m=>m.project_id===project_id&&m.user_id===p.id)){data().members.push({project_id,user_id:p.id,role,specialty});data().activity.unshift({id:Date.now(),project_id,task_id:null,actor_id:p.id,action:'member_joined',details:{role,specialty},created_at:new Date().toISOString()});}data().invites.unshift({code,email,project_id,role,accepted_at:null});save();}
 let url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('invite',code);state.lastInviteLink=url.toString();state.modal='invite-link';render();toast(isLive?'تم إعداد دعوة التسجيل':'هذه دعوة تجريبية؛ تم إضافة المستخدم محليًا');}
async function taskStatus(id,status){let t=data().tasks.find(x=>x.id===id);if(!t)return;let allow=canManage(t.project_id);if(!allow&&t.assigned_to!==me())return toast('هذه المهمة ليست مخصصة لك',true);if(status==='done'&&!allow)return toast('اعتماد المهمة النهائية لمدير المشروع',true);if(t.status===status)return;let from=t.status;if(isLive){const {error}=await sb.from('tasks').update({status}).eq('id',id);if(error){render();return toast(error.message,true);}await refreshLive();}else{t.status=status;t.updated_at=new Date().toISOString();t.updated_by=me();localLog(t.project_id,t,'status_changed',{from,to:status});if(status==='review')localNotifyManagers(t.project_id,t,'مهمة بانتظار مراجعتك');else if(status==='done')localNotify(t.assigned_to,t.project_id,t,'تم اعتماد مهمتك');else if(from==='review')localNotify(t.assigned_to,t.project_id,t,'أعيدت المهمة إليك: '+stageName(status));save();}render();toast(status==='review'?'أُرسلت المهمة للمراجعة وتم تنبيه المدير':'تم تحديث حالة المهمة');}
async function editTask(id,form){let t=data().tasks.find(x=>x.id===id);if(!t||!canManage(t.project_id))return toast('لا تملك صلاحية توزيع هذه المهمة',true);let vals={assigned_to:form.get('assigned_to')||null,due_date:form.get('due_date')||null,priority:form.get('priority'),description:String(form.get('description')||'')};if(isLive){let{error}=await sb.from('tasks').update(vals).eq('id',id);if(error)return toast(error.message,true);await refreshLive();}else{let prev={...t};Object.assign(t,vals,{updated_at:new Date().toISOString(),updated_by:me()});if(prev.assigned_to!==t.assigned_to){localLog(t.project_id,t,'assigned',{to:t.assigned_to});localNotify(t.assigned_to,t.project_id,t,'أُسندت إليك مهمة');}if(prev.due_date!==t.due_date||prev.priority!==t.priority||prev.description!==t.description)localLog(t.project_id,t,'task_edited');save();}state.modal='task:'+id;render();toast('تم حفظ المسؤول والموعد');}
async function addComment(id,body){let t=data().tasks.find(x=>x.id===id);if(!t||!canAccess(t.project_id))return toast('غير مسموح',true);if(isLive){let{error}=await sb.from('task_comments').insert({task_id:id,author_id:me(),body});if(error)return toast(error.message,true);await refreshLive();}else{data().comments.push({id:uid(),task_id:id,author_id:me(),body,created_at:new Date().toISOString()});localLog(t.project_id,t,'commented',{body:body.slice(0,140)});localNotify(t.assigned_to,t.project_id,t,'تعليق جديد على مهمتك',body.slice(0,140));if(!canManage(t.project_id))localNotifyManagers(t.project_id,t,'تعليق جديد: '+t.title);save();}render();toast('تمت إضافة التعليق');}
async function deleteTask(id){let t=data().tasks.find(x=>x.id===id);if(!t||!canManage(t.project_id))return toast('لا تملك صلاحية حذف هذه المهمة',true);if(!confirm('حذف المهمة «'+t.title+'» نهائياً؟'))return;if(isLive){let{error}=await sb.from('tasks').delete().eq('id',id);if(error)return toast(error.message,true);state.modal=null;await refreshLive();}else{localLog(t.project_id,null,'task_deleted',{title:t.title});data().tasks=data().tasks.filter(x=>x.id!==id);save();state.modal=null;render();}toast('تم حذف المهمة');}
async function removeMember(project_id,user_id){let m=data().members.find(x=>x.project_id===project_id&&x.user_id===user_id);if(!m)return;if(!(owner()||(canManage(project_id)&&m.role==='member')))return toast('لا تملك صلاحية إزالة هذا العضو',true);if(!confirm('إزالة '+profile(user_id).full_name+' من '+projectName(project_id)+'؟ مهامه المفتوحة تصير بدون مسؤول.'))return;if(isLive){let{error}=await sb.from('project_members').delete().match({project_id,user_id});if(error)return toast(error.message,true);await refreshLive();}else{data().members=data().members.filter(x=>x!==m);data().tasks.forEach(t=>{if(t.project_id===project_id&&t.assigned_to===user_id)t.assigned_to=null});localLog(project_id,null,'member_removed',{user:user_id});save();render();}toast('تمت إزالة العضو');}
async function markNotificationsRead(){if(!unreadCount())return;let now=new Date().toISOString();myNotifications().forEach(n=>{if(!n.read_at)n.read_at=now});if(isLive){await sb.rpc('mark_notifications_read');}else save();let c=el('notif-count');if(c)c.hidden=true;}
const appUrl=()=>location.origin+location.pathname;
async function handleAuth(form){let email=form.get('email')?.trim(),password=form.get('password'),name=form.get('name')?.trim();if(state.authPage==='recovery'){if(password!==form.get('password2'))return toast('كلمتا المرور غير متطابقتين',true);const{error}=await sb.auth.updateUser({password});if(error)return toast(error.message,true);state.authPage='login';history.replaceState({},'',location.pathname);toast('تم تغيير كلمة المرور بنجاح');return refreshLive();}if(state.authPage==='signup'){const{error,data:d}=await sb.auth.signUp({email,password,options:{data:{full_name:name},emailRedirectTo:appUrl()+(state.invitation?'?invite='+encodeURIComponent(state.invitation):'')}});if(error)return toast(error.message,true);state.authPage='login';render();toast(d?.session?'تم إنشاء الحساب':'تحقق من بريدك لتأكيد الحساب ثم سجل الدخول');if(d?.session)await refreshLive();}else if(state.authPage==='forgot'){let{error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:appUrl()});if(error)return toast(error.message,true);toast('تم إرسال رابط استعادة كلمة المرور');}else{const{error}=await sb.auth.signInWithPassword({email,password});if(error)return toast('بيانات الدخول غير صحيحة أو الحساب غير مؤكد',true);await refreshLive();}}
let dragId=null;
document.addEventListener('click',async e=>{if(e.target.closest('select,input,textarea'))return;const target=e.target.closest('button,[data-task-detail]');if(!target)return;if(target.closest('.modal')===null&&e.target.closest('[data-close-overlay]'))return;
 if(target.dataset.view){state.projectId=null;if(target.dataset.view==='activity'){state.activityProject='all';state.activityPerson='all';}setView(target.dataset.view);return;}
 if(target.dataset.openProject){setView('project',target.dataset.openProject);return;}
 if(target.dataset.projectService){state.service=target.dataset.projectService;state.view='tasks';render();return;}
 if(target.dataset.deleteTask){await deleteTask(target.dataset.deleteTask);return;}
 if(target.dataset.removeMember){let [pid,u]=target.dataset.removeMember.split('|');await removeMember(pid,u);return;}
 if(target.dataset.activityProject){state.activityProject=target.dataset.activityProject;state.activityPerson='all';setView('activity');return;}
 if(target.dataset.modal==='notifications'){state.modal='notifications';render();await markNotificationsRead();return;}
 if(target.dataset.modal){if(target.dataset.modal==='invite'&&!managesAny())return toast('دعوة الأعضاء لمدير المشروع أو المدير العام فقط',true);if(target.dataset.modal==='task'&&!visibleProjects().some(p=>canManage(p.id)))return toast('ليس لديك مشروع يمكنك إدارة مهامه',true);state.modal=target.dataset.modal;render();return;}
 if(target.dataset.modalClose){state.modal=null;render();return;}
 if(target.dataset.taskDetail){state.modal='task:'+target.dataset.taskDetail;render();return;}
 if(target.dataset.copyInvite){let u=new URL(location.href);u.search='?invite='+encodeURIComponent(target.dataset.copyInvite);u.hash='';await copy(u.toString());return;}
 if(target.dataset.copyLink){await copy(state.lastInviteLink);return;}
 if(target.dataset.authPage){state.authPage=target.dataset.authPage;render();return;}
 if(target.dataset.saveProfile){let name=el('my-fullname')?.value?.trim();if(!name)return;let {error}=await sb.from('profiles').update({full_name:name}).eq('id',me());if(error)return toast(error.message,true);await refreshLive();toast('تم حفظ الاسم');return;}
 if(target.dataset.resetDemo){if(confirm('هل تريد حذف بيانات التجربة على هذا الجهاز؟')){try{localStorage.removeItem(DEMO_KEY);}catch(e){}state.data=baseSeed();state.user='owner';state.view='dashboard';render();toast('تمت إعادة ضبط التجربة');}return;}
 if(target.id==='signout'){await sb.auth.signOut();return;}
});
async function copy(s){try{await navigator.clipboard.writeText(s);toast('تم نسخ الرابط');}catch(e){window.prompt('انسخ الرابط:',s);}}
document.addEventListener('click',e=>{if(e.target?.dataset?.closeOverlay&&e.target.classList.contains('modal-back')){state.modal=null;render();}});
document.addEventListener('submit',async e=>{e.preventDefault();let id=e.target.id,f=new FormData(e.target),button=e.target.querySelector('[type=submit]');if(button)button.disabled=true;try{if(id==='form-project')await projectCreate(f);if(id==='form-task')await taskCreate(f);if(id==='form-invite')await inviteCreate(f);if(id==='form-auth')await handleAuth(f);if(id==='form-task-edit')await editTask(e.target.dataset.taskId,f);if(id==='form-comment')await addComment(e.target.dataset.taskId,String(f.get('body')||'').trim());}catch(err){console.error(err);toast('تعذر إكمال الطلب: '+(err.message||err),true)}finally{if(button)button.disabled=false}});
document.addEventListener('change',async e=>{let x=e.target;if(x.id==='demo-user'){state.user=x.value;state.view='dashboard';state.projectId=null;render();return;}if(x.id==='task-project-filter'){state.projectId=x.value==='all'?null:x.value;state.service='all';render();return;}if(x.id==='team-project-filter'){state.projectId=x.value;render();return;}if(x.id==='task-service-filter'){state.service=x.value;render();return;}if(x.id==='activity-project-filter'){state.activityProject=x.value;render();return;}if(x.id==='activity-person-filter'){state.activityPerson=x.value;render();return;}if(x.dataset.taskStatus){let modal=state.modal;await taskStatus(x.dataset.taskStatus,x.value);if(modal?.startsWith('task:')){state.modal=modal;render();}return;}if(x.id==='form-task-project'){let p=x.value;el('form-task-service').innerHTML=projectServices(p).map(s=>`<option>${esc(s)}</option>`).join('');el('form-task-assignee').innerHTML='<option value="">غير معين</option>'+projTeam(p).map(m=>`<option value="${m.user_id}">${esc(profile(m.user_id).full_name)}</option>`).join('');}});
document.addEventListener('input',e=>{let x=e.target;if(x.id==='project-search'||x.id==='task-search'){let sel=x.selectionStart;state.search=x.value;let id=x.id;render();let input=el(id);if(input){input.focus();input.setSelectionRange(sel,sel);}}});
document.addEventListener('dragstart',e=>{let a=e.target.closest('[draggable=true]');if(a){dragId=a.dataset.taskDetail;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId);}});
document.addEventListener('dragover',e=>{let col=e.target.closest('[data-drop-stage]');if(col&&dragId){e.preventDefault();col.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{let col=e.target.closest('[data-drop-stage]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over')});
document.addEventListener('drop',async e=>{let col=e.target.closest('[data-drop-stage]');if(col&&dragId){e.preventDefault();let id=dragId;dragId=null;document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));await taskStatus(id,col.dataset.dropStage)}});
document.addEventListener('dragend',()=>{dragId=null;document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render();}});
start();
})();
